pub fn unregistered() -> &'static Self {
    static UNREGISTERED: Descriptors = Descriptors {
        inherits: Some(Inherits::True),
        syntax: Some(SyntaxDescriptor::universal()),
        initial_value: None,
    };
    &UNREGISTERED
}

